// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts) public {
        Reverter actor = new Reverter();
        ts = bound(ts, 1, type(uint256).max);
        vm.warp(ts);
        blockNum = bound(blockNum, block.number + 1, type(uint256).max - 1);
        vm.roll(blockNum);

        uint256 amount = 10 ether;
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: with a reverting receiver, the call must revert precisely
        // when the payout branch (block.number % 15 == 0) is taken, because the
        // payout transfer to the failing receiver reverts the whole call.
        assertTrue(!(blockNum % 15 == 0) || !ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
